import json, pathlib
p=pathlib.Path(__file__).with_name('additional_rust_pfp_foundations_supplement.json')
d=json.loads(p.read_text(encoding='utf-8'))
rows=[
('RPF-F046','medium','Prime host accepts a timeout budget but never enforces it','host/intake.rs',[[108,124]],'timeout_ms is range-checked and committed, but the complete host.rs/host/prime_execution.rs path never reads elapsed time or propagates a deadline to solve/replay. Add an enforceable work/deadline mechanism or identify this field explicitly as external supervisor metadata.','Source-established; no expensive solver run or observed wall-clock overrun. Dense-size fences remain real.'),
('RPF-F047','high','Challenge commit-reveal gate does not bind the revealed judge','challenge.rs',[[40,64],[253,274]],'Changing hidden cases, checker IDs/operator/version, judge commitment hash and timestamp passes the prerequisite verifier with the original commitment/freeze/deliverable. manifest_sha256 is never compared to a canonical reveal, and variable operator/version concatenation admits an exact field-boundary alias. Bind and verify a canonical framed judge manifest, checker identities and independently anchored event order; validate None authority.','Synthetic in-memory unchanged-owner probe; not a SHA collision, not a private benchmark attack or deployed exploit.'),
('RPF-F048','high','Challenge scoring passes the answer-bearing full case to the candidate','challenge.rs',[[199,211],[215,249],[302,323],[386,393]],'ExactMatchChecker reads expected_field from case, while evaluator serializes that entire case as the candidate command argument. Echoing that object is Correct for both checkers; checker independence/IDs are never enforced and the same object can be supplied twice. Separate public candidate input from judge-only expected data and bind distinct checker implementations to the reveal.','Pure checker probe models source-proven argument construction; no sandbox execution, actual cases or private key accessed. Arbitrary custom checkers may use different case conventions.'),
('RPF-F049','medium','Checker panics escape the advertised CheckerDefectPause boundary','challenge.rs',[[215,250]],'evaluate_dual_checkers handles returned Err values but calls each trait implementation without panic isolation. Synthetic checker panic unwinds instead of producing CheckerDefectPause. Specify a nonpanicking checker contract and isolate untrusted checkers, or catch recoverable unwind at a suitable boundary while preserving crash distinction.','Recovered by the probe outside the unchanged function; panic=abort cannot be caught. Does not show Rust memory unsafety.')]
for ident,severity,title,file,ranges,detail,limits in rows:
    v={'id':ident,'severity':severity,'title':title,'evidence':[{'path':'code/rust/pfp/src/'+file,'lines':r} for r in ranges],'status':'source-established' if ident=='RPF-F046' else 'bounded unchanged-owner probe reproduced','detail':detail,'limits':limits}
    if not any(x['id']==ident for x in d['findings']):d['findings'].append(v)
v={'id':'RPF-V019','kind':'synthetic challenge commitment/checker boundary probes','details_file':'additional_rust_pfp_foundations_challenge_validation.json','limits':'Original challenge owner included unchanged and cached dependencies only. No sandbox/candidate process or actual/private cases; echo observation is an in-memory checker test plus source argument tracing.'}
if not any(x['id']==v['id'] for x in d['validation']):d['validation'].append(v)
c={'id':'RPF-C016','claim':'The primary host actually solves and replays a supplied finite cochain candidate, while explicitly withholding authority and broader source/application claims.','evidence':[{'path':'code/rust/pfp/src/host.rs','lines':[233,291]},{'path':'code/rust/pfp/src/host.rs','lines':[343,384]},{'path':'code/rust/pfp/src/host/intake.rs','lines':[203,228]},{'path':'code/rust/pfp/src/host/prime_execution.rs','lines':[360,432]}],'dependencies':['core_wdp solve/replay and carrier_manifest, core_functional exact witness semantics','Finite resource-fenced declared carrier and i128encoded before/candidate vectors','Trusted current-process execution and immutable internal witnesses'],'limitations':['No automatic proof that carrier/payload encodes the intended task; source IDs lacking bytes are explicitly bound-only.','Detector adequacy is a sampled two-byte-commitment distinction, not semantic completeness.','Some Prime000 laws remain partial; successful output admission remains Refused/unsigned_lab.','Declared timeout is not enforced; F046. No new full-host integration test run.']}
if not any(x['id']==c['id'] for x in d['claims']):d['claims'].append(c)
p.write_text(json.dumps(d,indent=2)+'\n',encoding='utf-8')
